    { on: null }
  >;
  unlessConflict<Conflict extends UnlessConflict>(
    conflictGetter: (scope: $scopify<El>) => Conflict,
  ): $expr_InsertUnlessConflict<
    El,
    // Expression<{
    //   __kind__: ExpressionKind.Insert;
    //   __element__: El;
    //   __cardinality__: Cardinality.One;
    //   __expr__: $expr_PathNode;
    //   __shape__: InsertShape<El>;
    // }>,
    Conflict
  >;
}>;

export type $expr_InsertUnlessConflict<
  El extends ObjectType = ObjectType,
  // Root extends InsertBaseExpression = InsertBaseExpression,
  Conflict extends UnlessConflict = UnlessConflict,
> = Expression<{
  __kind__: ExpressionKind.InsertUnlessConflict;
  __element__: Conflict["else"] extends TypeSet
    ? Conflict["else"]["__element__"]["__name__"] extends El["__name__"]
      ? El
      : $Object
    : El;
  __cardinality__: Conflict["else"] extends TypeSet
    ? Conflict["else"]["__cardinality__"]
    : Cardinality.AtMostOne;
  __expr__: InsertBaseExpression;
  __conflict__: Conflict;
}>;

function unlessConflict(
  this: $expr_Insert,
  conflictGetter?: (scope: TypeSet) => UnlessConflict,
) {
  const expr: any = {
    __kind__: ExpressionKind.InsertUnlessConflict,
    __element__: this.__element__,
    __cardinality__: Cardinality.AtMostOne,
    __expr__: this,
    // __conflict__: Conflict;
  };

  if (!conflictGetter) {
    expr.__conflict__ = { on: null };
    return $expressionify(expr);
  } else {
    const scopedExpr = $getScopedExpr(this.__expr__);
    const conflict = conflictGetter(scopedExpr);
    expr.__conflict__ = conflict;
    if (conflict.else) {
      expr.__cardinality__ = conflict.else.__cardinality__;
      if (this.__element__.__name__ !== conflict.else.__element__.__name__) {
        expr.__element__ = $getTypeByName("std::Object");
      }
    }
    return $expressionify(expr);
  }
}

export function $insertify(
  expr: Omit<$expr_Insert, "unlessConflict">,
): $expr_Insert {
  (expr as any).unlessConflict = unlessConflict.bind(expr as any);
  return expr as any;
}

export function $normaliseInsertShape(
  root: ObjectTypeSet,
  shape: { [key: string]: any },
  isUpdate = false,
): { [key: string]: TypeSet | { "+=": TypeSet } | { "-=": TypeSet } } {
  const newShape: {
    [key: string]: TypeSet | { "+=": TypeSet } | { "-=": TypeSet };
  } = {};

  const _shape: [string, any][] =
    shape.__element__?.__kind__ === TypeKind.namedtuple
      ? Object.keys((shape.__element__ as NamedTupleType).__shape__).map(
          (key) => [key, shape[key]],
        )
      : Object.entries(shape);
  for (const [key, _val] of _shape) {
    let val = _val;
    let setModify: string | null = null;
    if (isUpdate && _val != null && typeof _val === "object") {
      const valKeys = Object.keys(_val);
      if (
        valKeys.length === 1 &&
        (valKeys[0] === "+=" || valKeys[0] === "-=")
      ) {
        val = _val[valKeys[0]];
        setModify = valKeys[0];
      }
    }

    const pointer = root.__element__.__pointers__[key];

  Cond extends _.castMaps.orScalarLiteral<$.TypeSet<_std.$bool>>,
  LHS extends TernaryMergeOperators["if_else"]["lhs"],
  RHS extends ExtractRHS<TernaryMergeOperators["if_else"], LHS>,
>(op1: "if", cond: Cond, op2: "then", lhs: LHS, op3: "else", rhs: RHS): $.$expr_Operator<
  _.syntax.mergeObjectTypes<LHS["__element__"], RHS["__element__"]>,
  $.cardutil.multiplyCardinalities<$.cardutil.orCardinalities<$.cardutil.paramCardinality<LHS> , $.cardutil.paramCardinality<RHS>>, $.cardutil.paramCardinality<Cond>>
>;

function op(...args: any[]) {
  let op: string = "";
    let params: any[] = [];
    let defs: any[] | null | undefined = null;
    if (args.length === 2) {
      if (typeof args[0] === "string" && overloadDefs.Prefix[args[0]]) {
        op = args[0];
        params = [args[1]];
        defs = overloadDefs.Prefix[op];
      } else if (typeof args[1] === "string" && overloadDefs.Postfix[args[1]]) {
        op = args[1];
        params = [args[0]];
        defs = overloadDefs.Postfix[op];
      }
    } else if (args.length === 3) {
      if (typeof args[1] === "string") {
        op = args[1];
        params = [args[0], args[2]];
        defs = overloadDefs.Infix[op];
      }
    } else if (args.length === 5) {
      if (typeof args[1] === "string" && typeof args[3] === "string") {
        // Python-style if-else
        op = `${args[1]}_${args[3]}`;
        params = [args[0], args[2], args[4]];
        defs = overloadDefs.Ternary[op];
      }
    } else if (args.length === 6) {
      // Functional-style if-then-else
      if (typeof args[0] === "string" && typeof args[2] === "string" && typeof args[4] === "string") {
        op = `${args[0]}_${args[4]}`;
        params = [args[3], args[1], args[5]];
        defs = overloadDefs.Ternary[op];
      }
    }

    if (!defs) {
      throw new Error(`No operator exists with signature: ${args.map(arg => `${arg}`).join(", ")}`);
    }

  const {kind, returnType, cardinality, args: resolvedArgs} = _.syntax.$resolveOverload(op, params, _.spec, defs);

  return _.syntax.$expressionify({
    __kind__: $.ExpressionKind.Operator,
    __element__: returnType,
    __cardinality__: cardinality,
    __name__: op,
    __opkind__: kind,
    __args__: resolvedArgs,
  }) as any;
};


